package com.meridiantrust.sentinel.repo;
import com.meridiantrust.sentinel.domain.Domain.*; import org.springframework.data.jpa.repository.*; import java.time.*; import java.util.*;
public final class Repositories { private Repositories(){} public interface Customers extends JpaRepository<Customer,Long>{Optional<Customer> findByExternalId(String id);} public interface Accounts extends JpaRepository<Account,Long>{Optional<Account> findByAccountNumber(String n);} public interface Txs extends JpaRepository<Tx,Long>{ boolean existsByExternalId(String id); List<Tx> findByAccountIdAndTimestampBetween(Long id,Instant from,Instant to); List<Tx> findByAccountCustomerIdAndTimestampBetween(Long id,Instant from,Instant to); } public interface Alerts extends JpaRepository<Alert,Long>{ List<Alert> findAllByOrderByRiskScoreDescCreatedAtDesc(); Optional<Alert> findByAccountIdAndRuleCodeAndDedupeKey(Long a,String r,String d); } public interface Cases extends JpaRepository<Case,Long>{} public interface Audits extends JpaRepository<Audit,Long>{} public interface Rules extends JpaRepository<RuleConfig,String>{} public interface Fx extends JpaRepository<FxRate,String>{} }
